func (b *BeaconState) initializeMerkleLayers(ctx context.Context) error {
	if len(b.merkleLayers) > 0 { return nil }
	fieldRoots, err := ComputeFieldRootsWithHasher(ctx, b)
	if err != nil { return err }
	layers := stateutil.Merkleize(fieldRoots)
	b.merkleLayers = layers
	switch b.version {
	case version.Phase0: b.dirtyFields = make(map[types.FieldIndex]bool, params.BeaconConfig().BeaconStateFieldCount)
	case version.Altair: ...
	case version.Fulu: b.dirtyFields = make(map[types.FieldIndex]bool, params.BeaconConfig().BeaconStateFuluFieldCount)
	default: return fmt.Errorf("unknown state version (%s) when computing dirty fields", version.String(b.version))
	}
	return nil
}
